    Specification<Product> spec = Specification.where(null);
    if (category != null) spec = spec.and(ProductSpec.hasCategory(category));
    if (minPrice != null) spec = spec.and(ProductSpec.priceGreaterThan(minPrice));
    if (maxPrice != null) spec = spec.and(ProductSpec.priceLessThan(maxPrice));
    if (inStock != null)  spec = spec.and(ProductSpec.isInStock(inStock));
    return productRepository.findAll(spec, pageable);
}

// Specification builders — reusable, composable
public class ProductSpec {
    public static Specification<Product> hasCategory(String category) {
        return (root, query, cb) -> cb.equal(root.get("category"), category);
    }
    public static Specification<Product> priceGreaterThan(BigDecimal min) {
        return (root, query, cb) -> cb.greaterThanOrEqualTo(root.get("price"), min);
    }
    public static Specification<Product> priceLessThan(BigDecimal max) {
        return (root, query, cb) -> cb.lessThanOrEqualTo(root.get("price"), max);
    }
    public static Specification<Product> isInStock(boolean inStock) {
        return (root, query, cb) -> cb.equal(root.get("inStock"), inStock);
    }
}

// Repository must extend JpaSpecificationExecutor
public interface ProductRepository extends JpaRepository<Product, Long>,
        JpaSpecificationExecutor<Product> {}
