// Each specification is a single, testable filter condition
public class ProductSpecifications {

    public static Specification<Product> hasCategory(String category) {
        return (root, query, criteriaBuilder) ->
            criteriaBuilder.equal(root.get("category"), category);
    }

    public static Specification<Product> priceBetween(BigDecimal min, BigDecimal max) {
        return (root, query, criteriaBuilder) ->
            criteriaBuilder.between(root.get("price"), min, max);
    }

    public static Specification<Product> nameContains(String keyword) {
        return (root, query, criteriaBuilder) ->
            criteriaBuilder.like(
                criteriaBuilder.lower(root.get("name")),
                "%" + keyword.toLowerCase() + "%");
    }
}

// Composing specifications dynamically in the service layer
public Page<Product> search(ProductFilter filter, Pageable pageable) {
    Specification<Product> spec = Specification.where(null); // start empty

    if (filter.getCategory() != null)
        spec = spec.and(ProductSpecifications.hasCategory(filter.getCategory()));
    if (filter.getMinPrice() != null && filter.getMaxPrice() != null)
        spec = spec.and(ProductSpecifications.priceBetween(
            filter.getMinPrice(), filter.getMaxPrice()));
    if (filter.getKeyword() != null)
        spec = spec.and(ProductSpecifications.nameContains(filter.getKeyword()));

    return productRepository.findAll(spec, pageable);
}
