@PutMapping("/api/users/{id}")
public UserDto replaceUser(@PathVariable Long id,
                           @Valid @RequestBody UserRequest request) {
    User user = userRepository.findById(id)
        .orElseThrow(() -> new ResourceNotFoundException("User", id));
    // Replace ALL fields — null if not provided
    user.setName(request.getName());
    user.setEmail(request.getEmail());
    user.setPhone(request.getPhone());  // null if not in body
    return toDto(userRepository.save(user));
}

// PATCH — partial update, only sent fields are changed
@PatchMapping("/api/users/{id}")
public UserDto patchUser(@PathVariable Long id,
                         @RequestBody Map<String, Object> updates) {
    User user = userRepository.findById(id)
        .orElseThrow(() -> new ResourceNotFoundException("User", id));
    // Only update fields present in the request
    if (updates.containsKey("name"))  user.setName((String) updates.get("name"));
    if (updates.containsKey("email")) user.setEmail((String) updates.get("email"));
    if (updates.containsKey("phone")) user.setPhone((String) updates.get("phone"));
    return toDto(userRepository.save(user));
}

