@RestControllerAdvice
public class ValidationExceptionHandler {

    // Handle @Valid @RequestBody validation failures
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ValidationErrorResponse> handleValidation(
            MethodArgumentNotValidException ex, HttpServletRequest request) {

        List<FieldErrorDetail> fieldErrors = ex.getBindingResult()
            .getFieldErrors().stream()
            .map(error -> new FieldErrorDetail(
                error.getField(),              // "email"
                error.getDefaultMessage(),     // "must be a valid email"
                error.getRejectedValue()))     // "not-an-email"
            .toList();

        ValidationErrorResponse response = new ValidationErrorResponse(
            LocalDateTime.now(), 400, "Validation Failed",
            fieldErrors.size() + " field(s) have errors",
            request.getRequestURI(), fieldErrors);

        return ResponseEntity.badRequest().body(response);
    }

    // Handle @Validated method-level validation failures
    @ExceptionHandler(ConstraintViolationException.class)
    public ResponseEntity<ValidationErrorResponse> handleConstraint(
            ConstraintViolationException ex, HttpServletRequest request) {

        List<FieldErrorDetail> fieldErrors = ex.getConstraintViolations()
            .stream()
            .map(v -> new FieldErrorDetail(
                v.getPropertyPath().toString(),
                v.getMessage(),
                v.getInvalidValue()))
            .toList();

        ValidationErrorResponse response = new ValidationErrorResponse(
            LocalDateTime.now(), 400, "Validation Failed",
            "Request parameter validation failed",
            request.getRequestURI(), fieldErrors);

        return ResponseEntity.badRequest().body(response);
    }
}

